-- Replace the whole product catalogue with Menu_Hardi_Kopi_Gabungan_NEW.xlsx
-- (all outlets; DINE IN price -> Dine In + Take Away, DELIVERY -> GrabFood; empty price = not sold on that channel).
-- Also clears all orders, POS journals/stock usage and recipes, as approved on 2026-11-07.
SET autocommit = 0;
START TRANSACTION;

-- Give back the stock consumed by POS sales, then drop those movements.
UPDATE inventory_stocks s
JOIN (SELECT outlet_id, stock_item_id, SUM(qty) AS q FROM inventory_movements
      WHERE movement_type = 'SALE_OUT' AND reference_type = 'ORDER' GROUP BY outlet_id, stock_item_id) m
  ON m.outlet_id = s.outlet_id AND m.stock_item_id = s.stock_item_id
SET s.qty_on_hand = s.qty_on_hand + m.q;
DELETE FROM inventory_movements WHERE movement_type = 'SALE_OUT' AND reference_type = 'ORDER';
DELETE jl FROM journal_lines jl JOIN journal_entries je ON je.id = jl.journal_entry_id WHERE je.source_type IN ('ORDER_SALE','ORDER_COGS');
DELETE FROM journal_entries WHERE source_type IN ('ORDER_SALE','ORDER_COGS');
DELETE FROM payments;
DELETE FROM order_items;
DELETE FROM orders;
UPDATE dining_tables SET status = 'AVAILABLE' WHERE status = 'OCCUPIED';
DELETE FROM outlet_products;
DELETE FROM recipe_items;
DELETE FROM recipes;
DELETE FROM products;
DELETE FROM categories;



COMMIT;
SET autocommit = 1;
ALTER TABLE orders AUTO_INCREMENT = 1;
ALTER TABLE order_items AUTO_INCREMENT = 1;
ALTER TABLE payments AUTO_INCREMENT = 1;
ALTER TABLE recipes AUTO_INCREMENT = 1;
ALTER TABLE recipe_items AUTO_INCREMENT = 1;
ALTER TABLE outlet_products AUTO_INCREMENT = 1;
ALTER TABLE products AUTO_INCREMENT = 1;
ALTER TABLE categories AUTO_INCREMENT = 1;
